import React, { useState, useEffect } from 'react';
import axios from 'axios';

const AboutUs = () => {
  const [officers, setOfficers] = useState([]);

  useEffect(() => {
    const fetchOfficers = async () => {
      try {
        const response = await axios.get('http://localhost:3001/about');
        setOfficers(response.data);
      } catch (error) {
        console.error('Error fetching officers:', error);
      }
    };

    fetchOfficers();
  }, []);

  return (
    <div>
      <h1>About Us</h1>
      <div className="officer-container">
        {officers.map((officer) => (
          <div key={officer.id} className="officer-card">
            <img src={`http://localhost:3001/uploads/${officer.photo}`} alt={officer.fullName} />
            <h2>{officer.fullName}</h2>
            <h3>{officer.title}</h3>
            <p>{officer.description}</p>
            {officer.email && <p>Email: {officer.email}</p>}
            {officer.phoneNumber && <p>Phone: {officer.phoneNumber}</p>}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AboutUs;
